CREATE TABLE IF NOT EXISTS "expense_categories" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"branchId" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT TRUE,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "expense_categories_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE,CONSTRAINT "expense_categories_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "branches"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "expense_categories_tenant_branch_code_key" ON "expense_categories" ("tenantId","branchId","code");
CREATE INDEX IF NOT EXISTS "expense_categories_tenant_branch_active_idx" ON "expense_categories" ("tenantId","branchId","isActive");
CREATE TABLE IF NOT EXISTS "recurring_expenses" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"branchId" TEXT NOT NULL,"categoryId" TEXT,"vendorId" TEXT,"category" TEXT NOT NULL,"amount" DECIMAL(12,2) NOT NULL,"reason" TEXT NOT NULL,"description" TEXT NOT NULL DEFAULT '',"payee" TEXT NOT NULL DEFAULT '',"paymentMethod" TEXT NOT NULL DEFAULT 'BANK',"taxDeductible" BOOLEAN NOT NULL DEFAULT FALSE,"frequency" TEXT NOT NULL,"nextRunAt" TIMESTAMP(3) NOT NULL,"lastRunAt" TIMESTAMP(3),"active" BOOLEAN NOT NULL DEFAULT TRUE,"createdById" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "recurring_expenses_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "tenants"("id") ON DELETE CASCADE,CONSTRAINT "recurring_expenses_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "branches"("id") ON DELETE CASCADE,CONSTRAINT "recurring_expenses_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "expense_categories"("id") ON DELETE SET NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "recurring_expenses_idempotencyKey_key" ON "recurring_expenses" ("idempotencyKey");
CREATE INDEX IF NOT EXISTS "recurring_expenses_due_idx" ON "recurring_expenses" ("tenantId","branchId","active","nextRunAt");
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "categoryId" TEXT;
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "vendorId" TEXT;
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "approvalStatus" TEXT NOT NULL DEFAULT 'APPROVED';
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "approvedById" TEXT;
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "approvedAt" TIMESTAMP(3);
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "approvalReason" TEXT;
ALTER TABLE "expenses" ADD COLUMN IF NOT EXISTS "recurringExpenseId" TEXT;
ALTER TABLE "expenses" ADD CONSTRAINT "expenses_categoryId_fkey" FOREIGN KEY ("categoryId") REFERENCES "expense_categories"("id") ON DELETE SET NULL;
ALTER TABLE "expenses" ADD CONSTRAINT "expenses_recurringExpenseId_fkey" FOREIGN KEY ("recurringExpenseId") REFERENCES "recurring_expenses"("id") ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS "expenses_tenant_branch_vendor_idx" ON "expenses" ("tenantId","branchId","vendorId");
CREATE INDEX IF NOT EXISTS "expenses_tenant_branch_approval_idx" ON "expenses" ("tenantId","branchId","approvalStatus","incurredAt");
CREATE TABLE IF NOT EXISTS "expense_approvals" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"branchId" TEXT NOT NULL,"expenseId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"requestedById" TEXT NOT NULL,"decidedById" TEXT,"decidedAt" TIMESTAMP(3),"reason" TEXT,"idempotencyKey" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "expense_approvals_expenseId_fkey" FOREIGN KEY ("expenseId") REFERENCES "expenses"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "expense_approvals_expenseId_key" ON "expense_approvals" ("expenseId");
CREATE UNIQUE INDEX IF NOT EXISTS "expense_approvals_idempotencyKey_key" ON "expense_approvals" ("idempotencyKey");
CREATE INDEX IF NOT EXISTS "expense_approvals_tenant_branch_status_idx" ON "expense_approvals" ("tenantId","branchId","status","createdAt");
CREATE TABLE IF NOT EXISTS "expense_attachments" ("id" TEXT NOT NULL PRIMARY KEY,"tenantId" TEXT NOT NULL,"branchId" TEXT NOT NULL,"expenseId" TEXT NOT NULL,"fileName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"contentBase64" TEXT,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "expense_attachments_expenseId_fkey" FOREIGN KEY ("expenseId") REFERENCES "expenses"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "expense_attachments_expense_hash_key" ON "expense_attachments" ("expenseId","sha256");
CREATE INDEX IF NOT EXISTS "expense_attachments_tenant_branch_expense_idx" ON "expense_attachments" ("tenantId","branchId","expenseId","createdAt");